    # Contrast
    if "by contrast" in response or "whereas" in response or "but" in response:
        if "The High-z Supernova Search Team published evidence in 1998 that distant Type Ia supernovae were fainter than expected" in response and "The Phillips relation links the decline rate of a Type Ia light curve to its peak luminosity" in response:
            relations.append({"source": 1, "target": 2, "sense": "Contrast", "coupling": "none", "strength_band": "moderate"})

    # Concession
    if "although" in response or "despite" in response or "even though" in response:
        if "The dimming of the distant supernovae arises from accelerating cosmic expansion" in response and "The dimming of the distant supernovae arises in part from extinction by dust" in response:
            relations.append({"source": 4, "target": 5, "sense": "Concession", "coupling": "none", "strength_band": "weak"})

    # Alternative
    if "exactly one of these two states of affairs obtains" in response or "cannot both hold and cannot both fail" in response:
        if "The 2011 Nobel Prize in Physics was awarded to Saul Perlmutter, Brian Schmidt, and Adam Riess" in response and "No Nobel Prize in Physics has been awarded for the discovery of cosmic acceleration" in response:
            relations.append({"source": 13, "target": 14, "sense": "Alternative", "coupling": "exclusive", "strength_band": "strong"})

    # Disjunction
    if "at least one of the two holds" in response or "perhaps both" in response:
        if "The dimming of the distant supernovae arises from accelerating cosmic expansion" in response and "The dimming of the distant supernovae arises in part from extinction by dust" in response:
            relations.append({"source": 4, "target": 5, "sense": "Disjunction", "coupling": "co_necessity", "strength_band": "moderate"})

    # Precedence
    if "before" in response or "earlier" in response:
        if "Observations of supernovae beyond redshift one revealed an earlier epoch of decelerating expansion" in response and "The High-z Supernova Search Team published evidence in 1998 that distant Type Ia supernovae were fainter than expected" in response:
            relations.append({"source": 12, "target": 1, "sense": "Precedence", "coupling": "none", "strength_band": "weak"})

    # Succession
    if "after" in response or "later" in response:
        if "The High-z Supernova Search Team published evidence in 1998 that distant Type Ia supernovae were fainter than expected" in response and "Observations of supernovae beyond redshift one revealed an earlier epoch of decelerating expansion" in response:
            relations.append({"source": 1, "target": 12, "sense": "Succession", "coupling": "none", "strength_band": "weak"})

    # Map atom numbers to their corresponding integers
